Local lcCNPJ, lcIE

Select crReg1

lcCNPJ = Strtran(Strtran(Strtran(crSigCdEmp.Cgcs,[.],[]),[/],[]),[-],[])
lcIE   = Strtran(crSigCdEmp.IEs,[.],[])

Append Blank
Replace TipoReg  With [1],;
		CNPJ	 With lcCNPJ,;
		InscEst  With lcIE,;
		Razaos	 With fLimpaTexto(crSigCdEmp.Razsocs),;
		CodFinal With Str(ThisForm.GetFinal.ListIndex,1),;
		QtdRegT2 With Str(0,5),;
		DtLevEst With Dtoc(ThisForm.getDtEst.Value) in crReg1  

Return

LOCAL lnNumParc 

lnNumParc = ThisForm.getNumParc.Value 
If( ThisForm.TotalImposto <= 0 )
	lnNumParc = 0
Endif

Select crReg3

Append Blank in crReg3
Replace TipoReg 	With [3],;
		TotSldCred	With [0,00],;
		IcmTotDev	With Str(ThisForm.TotalImposto,12,2),;
		IcmRecEst   With Str(ThisForm.TotalImposto,12,2),;
		NumParcPag  With Str(lnNumParc,2) in crReg3 

Return

=fConfigGeral()

